    [B------:R-:W-:-:S04] @Pt3 IADD3.X Ro1, Pt0, PT, RZ, ~Ro1, RZ, Pt0, !PT
    [B------:R-:W-:-:S04] @Pt3 IADD3.X Ro2, Pt0, PT, RZ, ~Ro2, RZ, Pt0, !PT
