    [B------:R-:W-:-:S04] @Pt1 IADD3.X Ro6, Pt0, PT, Ro6, 0xFFFFFFFF, RZ, Pt0, !PT
    [B------:R-:W-:-:S04] @Pt1 IADD3.X Ro7, Pt0, PT, Ro7, 0xFFFFFFFF, RZ, Pt0, !PT
